namespace report;
table Config { seed:ulong; rows:ulong; heading:string; }
table Outputs { config:Config (required); }
root_type Outputs;

attribute "tsugumi";
namespace report;
table CsvFile { value:string; }
table Outputs { csv:CsvFile (required, tsugumi: "file"); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard { inherit sdk; src = ./src; };
}

